import React, { useState, useEffect } from 'react';
import { Card, Button, Form, Table } from 'react-bootstrap';
import { Bar } from 'react-chartjs-2';
import axios from 'axios';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const API_URL = 'http://localhost:5000/api';

function Scheduler() {
  const [algorithm, setAlgorithm] = useState('fcfs');
  const [processes, setProcesses] = useState([]);
  const [ganttData, setGanttData] = useState([]);
  const [stats, setStats] = useState({});

  const [newProcess, setNewProcess] = useState({
    name: '',
    arrival_time: '',
    burst_time: '',
    priority: ''
  });

  useEffect(() => {
    fetchProcesses();
  }, []);

  const fetchProcesses = async () => {
    try {
      const response = await axios.get(`${API_URL}/scheduler/processes`);
      setProcesses(response.data);
    } catch (error) {
      console.error('Error fetching processes:', error);
    }
  };

  const addProcess = async () => {
    if (!newProcess.name || !newProcess.arrival_time || !newProcess.burst_time || !newProcess.priority) {
      alert('Please fill all fields');
      return;
    }
    
    try {
      await axios.post(`${API_URL}/scheduler/processes`, {
        ...newProcess,
        arrival_time: parseInt(newProcess.arrival_time),
        burst_time: parseInt(newProcess.burst_time),
        priority: parseInt(newProcess.priority)
      });
      fetchProcesses();
      setNewProcess({ name: '', arrival_time: '', burst_time: '', priority: '' });
    } catch (error) {
      console.error('Error adding process:', error);
    }
  };

  const runScheduler = async () => {
    try {
      const response = await axios.post(`${API_URL}/scheduler/run`, { algorithm });
      setGanttData(response.data.gantt_chart);
      setStats(response.data.statistics);
    } catch (error) {
      console.error('Error running scheduler:', error);
    }
  };

  const ganttChartData = {
    labels: ganttData.map(entry => `P${entry.pid}`),
    datasets: [{
      label: 'Execution Time',
      data: ganttData.map(entry => entry.end_time - entry.start_time),
      backgroundColor: [
        'rgba(255, 99, 132, 0.6)',
        'rgba(54, 162, 235, 0.6)',
        'rgba(255, 206, 86, 0.6)',
        'rgba(75, 192, 192, 0.6)',
        'rgba(153, 102, 255, 0.6)',
      ]
    }]
  };

  return (
    <div className="scheduler fade-in">
      <h2 className="mb-4">CPU Scheduler</h2>

      <Card className="mb-4">
        <Card.Header>Add New Process</Card.Header>
        <Card.Body>
          <Form>
            <div className="row">
              <div className="col-md-3">
                <Form.Group>
                  <Form.Label>Process Name</Form.Label>
                  <Form.Control
                    type="text"
                    value={newProcess.name}
                    onChange={(e) => setNewProcess({...newProcess, name: e.target.value})}
                    placeholder="P1"
                  />
                </Form.Group>
              </div>
              <div className="col-md-3">
                <Form.Group>
                  <Form.Label>Arrival Time</Form.Label>
                  <Form.Control
                    type="number"
                    value={newProcess.arrival_time}
                    onChange={(e) => setNewProcess({...newProcess, arrival_time: parseInt(e.target.value)})}
                  />
                </Form.Group>
              </div>
              <div className="col-md-3">
                <Form.Group>
                  <Form.Label>Burst Time</Form.Label>
                  <Form.Control
                    type="number"
                    value={newProcess.burst_time}
                    onChange={(e) => setNewProcess({...newProcess, burst_time: parseInt(e.target.value)})}
                  />
                </Form.Group>
              </div>
              <div className="col-md-3">
                <Form.Group>
                  <Form.Label>Priority</Form.Label>
                  <Form.Control
                    type="number"
                    value={newProcess.priority}
                    onChange={(e) => setNewProcess({...newProcess, priority: parseInt(e.target.value)})}
                  />
                </Form.Group>
              </div>
            </div>
            <Button className="mt-3" onClick={addProcess}>Add Process</Button>
          </Form>
        </Card.Body>
      </Card>

      <Card className="mb-4">
        <Card.Header>Scheduling Algorithm</Card.Header>
        <Card.Body>
          <Form.Group>
            <Form.Label>Select Algorithm</Form.Label>
            <Form.Select value={algorithm} onChange={(e) => setAlgorithm(e.target.value)}>
              <option value="fcfs">First Come First Serve (FCFS)</option>
              <option value="sjf">Shortest Job First (SJF)</option>
              <option value="srtf">Shortest Remaining Time First (SRTF)</option>
              <option value="rr">Round Robin (RR)</option>
              <option value="priority">Priority Scheduling</option>
            </Form.Select>
          </Form.Group>
          <Button className="mt-3" onClick={runScheduler}>Run Scheduler</Button>
        </Card.Body>
      </Card>

      {stats.algorithm && (
        <Card className="mb-4">
          <Card.Header>Statistics</Card.Header>
          <Card.Body>
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-label">Avg Waiting Time</div>
                <div className="stat-value">{stats.avg_waiting_time}</div>
              </div>
              <div className="stat-card" style={{background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)'}}>
                <div className="stat-label">Avg Turnaround Time</div>
                <div className="stat-value">{stats.avg_turnaround_time}</div>
              </div>
              <div className="stat-card" style={{background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)'}}>
                <div className="stat-label">CPU Utilization</div>
                <div className="stat-value">{stats.cpu_utilization}%</div>
              </div>
            </div>
          </Card.Body>
        </Card>
      )}

      {ganttData.length > 0 && (
        <Card>
          <Card.Header>Gantt Chart</Card.Header>
          <Card.Body>
            <Bar data={ganttChartData} />
          </Card.Body>
        </Card>
      )}
    </div>
  );
}

export default Scheduler;
